# Build the two demonstrations from their regular grid descriptions and listed intersections.
d1=[[8]*18 for _ in range(27)]
for y in (1,9,17):
    for x in range(18): d1[y][x]=0
for y in range(27):
    for x in (1,16): d1[y][x]=0
for y,val in ((1,3),(9,3),(17,2)):
    for x in (1,16): d1[y][x]=val
# final boundary has only intersections
for x in (1,16): d1[26][x]=0
print('demo1', mod.transform(d1))
d2=[[6]*25 for _ in range(24)]
for y in (2,7,12,17,22):
    for x in range(25): d2[y][x]=4
for y in range(24):
    for x in (3,7,11,15,19,23): d2[y][x]=4
nodes=[[2,2,2,4,4,4],[2,2,2,7,7,4],[0,0,7,7,7,4],[0,0,7,7,0,0],[4,4,4,0,0,4]]
for i,y in enumerate((2,7,12,17,22)):
    for j,x in enumerate((3,7,11,15,19,23)): d2[y][x]=nodes[i][j]
print('demo2', mod.transform(d2))
